-- pages-1-estate.commit.sql
--
-- ============================== COMMIT - THIS WRITES ==============================
-- Byte-identical to the preflight twin except this banner and the terminal statement. The preflight is optional:
-- this file verifies everything inside its transaction and keeps nothing when a check fails.
--
-- WHAT THIS DOES, in one transaction on the estate database: declares the wildlife application's eight pages as
-- ui-page-definition.v1 revision 1 through sidefx_ui.stage_ui_page, points each page at that revision through
-- sidefx_ui.promote_ui_page, and reads every page back through analysis.read_ui_page_document.
-- Pages: /circuit/wildlife, /circuit/wildlife-collection, /circuit/wildlife-animal, /circuit/wildlife-capture, /circuit/wildlife-mine, /circuit/wildlife-team, /circuit/wildlife-home, /circuit/wildlife-refusals.
-- They render in the SideFX shell once it carries the observe results (sfx-platform page-runtime.js); an older
-- shell shows their refusals instead of running anything. WHERE: the estate database (a few seconds).
-- RESULT SETS: base (existing 0); one STAGED and one PROMOTED row per page; verify (8 rows, digest_matches 1, read_status READ).
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @pages TABLE(ordinal int PRIMARY KEY,page_id nvarchar(400) COLLATE Latin1_General_100_BIN2,path nvarchar(400) COLLATE Latin1_General_100_BIN2,
 document nvarchar(max),digest char(64) COLLATE Latin1_General_100_BIN2);
INSERT @pages VALUES(1,N'ui-page-wildlife',N'/circuit/wildlife',N'{"document":"ui-page-definition.v1","pageId":"ui-page-wildlife","namespaceId":"sidefx:ui","path":"/circuit/wildlife","revision":1,"title":"Wildlife Collection","layoutRef":{"layoutId":"ui-layout-marketing.v1","digest":"e2591ca34ce894541132dccaca54fa77d8e98b84e7f8c8c8c93ff320fe9db58c"},"navigation":{"items":[{"label":"Overview","href":"/circuit/wildlife"},{"label":"Collection","href":"/circuit/wildlife-collection"},{"label":"Animal","href":"/circuit/wildlife-animal"},{"label":"Capture","href":"/circuit/wildlife-capture"},{"label":"My animals","href":"/circuit/wildlife-mine"},{"label":"Team","href":"/circuit/wildlife-team"},{"label":"Home","href":"/circuit/wildlife-home"},{"label":"Refusals","href":"/circuit/wildlife-refusals"}]},"sources":[{"sourceId":"session","reader":"session"},{"sourceId":"catalog","reader":"catalog"}],"sections":[{"sectionId":"hero","regionId":"main","order":1,"component":{"kind":"hero","version":1},"props":{"eyebrow":"Wildlife Collection, citizen slice","headline":"Collect the wildlife around you","lede":"Browse the catalog, photograph what you find and build a team. Each screen runs a declared capability as you, and shows that capability''s own answer.","primaryActionId":"open-circuit"},"bindings":{"figure":{"kind":"read","reader":"scenario","input":{"capabilityId":"nerdery-record-animal-encounter","namespaceId":"sidefx:capabilities","page":"scenario-1"},"pointer":"/slides/0"}},"actions":[{"actionId":"open-circuit","kind":"navigate","to":"/circuit/explorer?capability=nerdery-record-animal-encounter&namespace=sidefx%3Acapabilities"}]},{"sectionId":"signed-in","regionId":"main","order":2,"component":{"kind":"stat","version":1},"props":{"label":"Signed in as"},"bindings":{"value":{"kind":"read","reader":"session","pointer":"/principalId"},"sub":{"kind":"read","reader":"session","pointer":"/expiresAt"}}},{"sectionId":"journey","regionId":"main","order":3,"component":{"kind":"card-li