llection","link":"/circuit/explorer?capability=nerdery-browse-animal-collection&namespace=sidefx%3Acapabilities","linkLabel":"Open circuit"},{"cardId":"nerdery-view-animal-definition","capabilityId":"nerdery-view-animal-definition","namespaceId":"sidefx:capabilities","title":"View an animal","body":"Read one animal with only the information this user has unlocked.","meta":"sidefx:capabilities/nerdery-view-animal-definition","link":"/circuit/explorer?capability=nerdery-view-animal-definition&namespace=sidefx%3Acapabilities","linkLabel":"Open circuit"},{"cardId":"nerdery-upload-encounter-photo","capabilityId":"nerdery-upload-encounter-photo","namespaceId":"sidefx:capabilities","title":"Upload a photo","body":"Keep the photo''s exact bytes under their digest for later verification.","meta":"sidefx:capabilities/nerdery-upload-encounter-photo","link":"/circuit/explorer?capability=nerdery-upload-encounter-photo&namespace=sidefx%3Acapabilities","linkLabel":"Open circuit"},{"cardId":"nerdery-record-animal-encounter","capabilityId":"nerdery-record-animal-encounter","namespaceId":"sidefx:capabilities","title":"Record an encounter","body":"Record one individual per request; a retry replays without a second write.","meta":"sidefx:capabilities/nerdery-record-animal-encounter","link":"/circuit/explorer?capability=nerdery-record-animal-encounter&namespace=sidefx%3Acapabilities","linkLabel":"Open circuit"},{"cardId":"nerdery-view-collected-animals","capabilityId":"nerdery-view-collected-animals","namespaceId":"sidefx:capabilities","title":"My animals","body":"List this user''s individuals with their photos and nicknames.","meta":"sidefx:capabilities/nerdery-view-collected-animals","link":"/circuit/explorer?capability=nerdery-view-collected-animals&namespace=sidefx%3Acapabilities","linkLabel":"Open circuit"},{"cardId":"nerdery-set-animal-team","capabilityId":"nerdery-set-animal-team","namespaceId":"sidefx:capabilities","title":"Set the team","body":"Save up to six of this user''s individuals against the revision the user saw.","meta":"sidefx:capabilities/nerdery-set-animal-team","link":"/circuit/explorer?capability=nerdery-set-animal-team&namespace=sidefx%3Acapabilities","linkLabel":"Open circuit"},{"cardId":"nerdery-view-wildlife-home","capabilityId":"nerdery-view-wildlife-home","namespaceId":"sidefx:capabilities","title":"Home","body":"Show this user''s saved team.","meta":"sidefx:capabilities/nerdery-view-wildlife-home","link":"/circuit/explorer?capability=nerdery-view-wildlife-home&namespace=sidefx%3Acapabilities","linkLabel":"Open circuit"},{"cardId":"nerdery-add-animal-definition","capabilityId":"nerdery-add-animal-definition","namespaceId":"sidefx:capabilities","title":"Add to the catalog","body":"Biologists add animal definitions; citizens are refused.","meta":"sidefx:capabilities/nerdery-add-animal-definition","link":"/circuit/explorer?capability=nerdery-add-animal-definition&namespace=sidefx%3Acapabilities","linkLabel":"Open circuit"}]}},{"sectionId":"data-note","regionId":"main","order":5,"component":{"kind":"text","version":1},"props":{"role":"note","text":"Synthetic catalog and people from the challenge fixtures. Identity, photos and encounters are stored by the slice''s own mechanics in the wildlife store."}}]}','193069c1cf3cb4fd7b2e3d4acbfefe346ea9241a97821170a0f448b132064bb3');
