INSERT @pages VALUES(8,N'ui-page-wildlife-refusals',N'/circuit/wildlife-refusals',N'{"document":"ui-page-definition.v1","pageId":"ui-page-wildlife-refusals","namespaceId":"sidefx:ui","path":"/circuit/wildlife-refusals","revision":1,"title":"Refusals","layoutRef":{"layoutId":"ui-layout-marketing.v1","digest":"e2591ca34ce894541132dccaca54fa77d8e98b84e7f8c8c8c93ff320fe9db58c"},"navigation":{"items":[{"label":"Overview","href":"/circuit/wildlife"},{"label":"Collection","href":"/circuit/wildlife-collection"},{"label":"Animal","href":"/circuit/wildlife-animal"},{"label":"Capture","href":"/circuit/wildlife-capture"},{"label":"My animals","href":"/circuit/wildlife-mine"},{"label":"Team","href":"/circuit/wildlife-team"},{"label":"Home","href":"/circuit/wildlife-home"},{"label":"Refusals","href":"/circuit/wildlife-refusals"}]},"sources":[{"sourceId":"session","reader":"session"}],"sections":[{"sectionId":"hero","regionId":"main","order":1,"component":{"kind":"hero","version":1},"props":{"eyebrow":"Boundaries","headline":"What the system refuses","lede":"Rules live in the capabilities, not in these screens. Each button sends a request the capability must refuse, and shows the refusal it names.","primaryActionId":"open-circuit"},"bindings":{"figure":{"kind":"read","reader":"scenario","input":{"capabilityId":"nerdery-add-animal-definition","namespaceId":"sidefx:capabilities","page":"scenario-1"},"pointer":"/slides/0"}},"actions":[{"actionId":"open-circuit","kind":"navigate","to":"/circuit/explorer?capability=nerdery-add-animal-definition&namespace=sidefx%3Acapabilities"}]},{"sectionId":"add-heading","regionId":"main","order":2,"component":{"kind":"heading","version":1},"props":{"text":"A citizen adds to the catalog","level":2}},{"sectionId":"add","regionId":"main","order":3,"component":{"kind":"section","version":1},"props":{"body":["Only biologists maintain the catalog. This sends a complete new animal as you, a citizen."],"actions":[{"actionId":"add","label":"Add Demo Owl as a